 "theme":   { "fr": "Mobilité — aide aux ménages modestes face aux restrictions de circulation", "nl": "Mobiliteit — steun aan huishoudens met lage inkomens bij verkeersbeperkingen", "en": "Mobility — support for low-income households facing traffic restrictions" },
 "matiere": { "key": "mobilite", "fr": "Mobilité", "nl": "Mobiliteit", "en": "Mobility" },
 "titre": { "fr": "Grenoble crée un « pass ZFE » de 1 000 euros par an pour les ménages privés de voiture par la zone à faibles émissions", "nl": "Grenoble voert een « ZFE-pas » van 1.000 euro per jaar in voor huishoudens die hun wagen door de lage-emissiezone verliezen", "en": "Grenoble creates a €1,000-a-year « ZFE pass » for households losing their car to the low emission zone" },
